const $ = selector => document.querySelector(selector);

document.addEventListener("DOMContentLoaded", () => {
  $("#email_form").addEventListener("submit", evt => {
    const email1 = $("#email_1").value.trim();
    const email2 = $("#email_2").value.trim();
    let isValid = true;

    $("#email_1").nextElementSibling.textContent = "";
    $("#email_2").nextElementSibling.textContent = "";
    if (email1 === "") {
      $("#email_1").nextElementSibling.textContent = "Email is required.";
      isValid = false;
    }
    if (email2 !== email1) {
      $("#email_2").nextElementSibling.textContent = "Emails must match.";
      isValid = false;
    }
    if (!isValid) {
      evt.preventDefault();
    }
  });
});

